class Ahrara < Formula
  desc "Disposable email with a local inbox for AI agents, QA and automation"
  homepage "https://ahrara.dev"
  license "MIT"

  # BEGIN RELEASE METADATA (generated by scripts/release-manifest.py)
  version "0.0.1"

  on_macos do
    on_arm do
      url "https://github.com/Hitmasu/Ahrara/releases/download/v0.0.1/ahrara-darwin-aarch64", using: :nounzip
      sha256 "2ff81c4654de3d01c8753e5972a6191c118e551c13b15ebd21efd3dfcf774e0a"
    end
    on_intel do
      url "https://github.com/Hitmasu/Ahrara/releases/download/v0.0.1/ahrara-darwin-x86_64", using: :nounzip
      sha256 "1df6173705a15b88c1668c531767f5bcb48c59fbb04aa391527863bb84f75948"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/Hitmasu/Ahrara/releases/download/v0.0.1/ahrara-linux-aarch64", using: :nounzip
      sha256 "3731cacafb1824d81c234f44dc4fb567fc1f43c22b7c7d15203e2de7bfbe2f1e"
    end
    on_intel do
      url "https://github.com/Hitmasu/Ahrara/releases/download/v0.0.1/ahrara-linux-x86_64", using: :nounzip
      sha256 "340534c1ffc17d31a427cbeeb3e477051d8e8f5433cb47dcc4a6465eb1952637"
    end
  end
  # END RELEASE METADATA

  def install
    libexec.install File.basename(stable.url) => "ahrara"
    chmod 0755, libexec/"ahrara"
    (libexec/"ahrara.install.json").write <<~JSON
      {"schema_version":1,"method":"brew"}
    JSON
    bin.install_symlink libexec/"ahrara"
  end

  test do
    assert_match "ahrara #{version}", shell_output("#{bin}/ahrara --version")
    output = shell_output("#{bin}/ahrara --config #{testpath}/unused/config.toml --json update")
    result = JSON.parse(output)
    assert_equal "brew", result.fetch("install_method")
    assert_equal false, result.fetch("updated")
    assert_match "brew upgrade ahrara", result.fetch("message")
    refute_path_exists testpath/"unused"
  end
end
